3. **Implement the plugin**

Open `src/plugin.ts` and replace its content with the following code. This implementation assumes that you have already set up the oneWelcome iOS SDK in your Xcode project and have the `SharedUserClient` instance available.

```typescript
import { PluginListenerHandle } from '@capacitor/core';
import { PluginListenerHandle, PluginListener } from '@capacitor/core';
import { Onegini } from 'one-welcome-sdk'; // Import the oneWelcome iOS SDK

interface OneWelcomePlugin {
  authenticateUser(options: { userProfile: string; authenticator?: string }): Promise<void>;
  addListener(eventName: 'authenticationStatus', listenerFunc: (data: AuthenticationStatusEvent) => void): Promise<PluginListenerHandle> & PluginListener;
  removeAllListeners(): Promise<void>;
}

interface AuthenticationStatusEvent {
  status: 'started' | 'pinChallenge' | 'biometricChallenge' | 'customAuthChallenge' | 'success' | 'failure';
  userProfile?: string;
  authenticator?: string;
  error?: string;
}

export class OneWelcomePlugin implements OneWelcomePlugin {
  private userClient: Onegini.SharedUserClient;
  private listeners: { [event: string]: PluginListener[] } = {};

  constructor() {
    this.userClient = Onegini.SharedUserClient.instance; // Assuming you have the SharedUserClient instance available
  }

  async authenticateUser(options: { userProfile: string; authenticator?: string }): Promise<void> {
    const { userProfile, authenticator } = options;

    this.userClient.authenticateUserWith(
      profile: userProfile,
      authenticator: authenticator,
      delegate: this
    );
  }

  addListener(eventName: 'authenticationStatus', listenerFunc: (data: AuthenticationStatusEvent) => void): Promise<PluginListenerHandle> & PluginListener {
    if (!this.listeners[eventName]) {
      this.listeners[eventName] = [];
    }

    this.listeners[eventName].push(listenerFunc);

    return {
      remove: () => {
        const index = this.listeners[eventName].indexOf(listenerFunc);
        if (index > -1) {
          this.listeners[eventName].splice(index, 1);
        }
      },
    };
  }

  removeAllListeners(): Promise<void> {
    this.listeners = {};
    return Promise.resolve();
  }

