Here's a function that should meet your requirements. It takes `currentRating` and `newRating` as parameters, and updates the classes of the rating buttons accordingly.

```javascript
function updateClasses(currentRating, newRating) {
  // Calculate rounded ratings and create arrays
  const currentRatingArr = Array.from({ length: 5 }, () => {
    const value = Math.round(currentRating / 20);
    currentRating -= value * 20;
    return value * 20;
  });

  const newRatingArr = Array.from({ length: 5 }, () => {
    const value = Math.round(newRating / 20);
    newRating -= value * 20;
    return value * 20;
  });

  // Create tuple array with change values
  const tuples = currentRatingArr.map((curr, index) => [
    curr,
    newRatingArr[index],
    curr !== newRatingArr[index],
  ]);

  // Update rating buttons
  document.querySelectorAll('.rating-button').forEach((btn, index) => {
    const [currentClass, newClass, hasChanged] = tuples[index];

    if (hasChanged) {
      btn.classList.remove(`r${currentClass}`);
      btn.classList.add(`r${newClass}`);
    }
  });
}
```

